93	    #[test]
94	    fn empty_input_matches_standard_sha256() {
95	        let digest = digest_reader(io::empty()).unwrap();
96	        assert_eq!(
97	            digest.to_hex(),
98	            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
99	        );
100	    }
