104	        let digest = digest_reader(&b"abc"[..]).unwrap();
105	        assert_eq!(
106	            digest.to_hex(),
107	            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
108	        );
109	    }
