112	    fn binary_and_non_utf8_bytes_hashed_verbatim() {
113	        let data: Vec<u8> = (0u8..=255).chain([0x00, 0xff, 0xfe, 0x80]).collect();
114	        let digest = digest_reader(&data[..]).unwrap();
115	        // 独立依据：python3 hashlib.sha256 对同样 260 字节的计算结果。
116	        assert_eq!(
117	            digest.to_hex(),
118	            "ae1754116b130744d081ccc09988962b3e875ec0e0d6194f2c950e8fe7e27a3d"
119	        );
