126	        struct FailingReader;
127	        impl Read for FailingReader {
128	            fn read(&mut self, _buf: &mut [u8]) -> io::Result<usize> {
129	                Err(io::Error::new(io::ErrorKind::Other, "boom"))
130	            }
131	        }
