262	    fn digest_representations_express_the_same_value() {
263	        let digest = digest_reader(&b"abc"[..]).unwrap();
264	        let hex = digest.to_hex();
265	
266	        // 原始字节与十六进制文本表达同一个值。
267	        let mut from_bytes = String::with_capacity(64);
268	        for byte in digest.as_bytes() {
269	            use std::fmt::Write as _;
270	            let _ = write!(from_bytes, "{byte:02x}");
271	        }
272	        assert_eq!(from_bytes, hex);
273	
274	        // Display 与 to_hex 一致。
275	        assert_eq!(format!("{digest}"), hex);
276	
277	        // 恰好 64 个小写十六进制字符，无文件名、标签、空白或换行。
278	        assert_eq!(hex.len(), 64);
279	        assert!(hex.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
280	        assert!(!hex.chars().any(char::is_whitespace));
281	    }
